// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    // Adversarial counterparty: c.withdraw sends to msg.sender, which is this
    // test contract. It deliberately has NO receive()/payable fallback, so a
    // `transfer` of nonzero value to it FAILS. The reference must then either
    // revert or move the ether; the mutant ignores the failure and returns ok.

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1e30);
        vm.deal(address(c), amount);

        uint256 before = address(c).balance;
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if withdraw reports success, exactly `amount` must
        // have left the contract; a failed payout can never look successful.
        assertTrue(!ok || address(c).balance == before - amount);
    }
}
